   try{Object actual=switch(op){case "P_EC","WB"->e.GetByteCount(c);case "P_EB","EB"->e.GetBytes(c);case "P_DC","WG"->e.GetCharCount(b);case "P_DB","DC"->e.GetChars(b);case "EA"->e.GetBytes(c,index,count,outBytes,offset);case "ES"->e.GetBytes(c==null?null:new String(c),index,count,outBytes,offset);case "DA"->e.GetChars(b,index,count,outChars,offset);case "CB"->e.GetByteCount(c,index,count);case "CC"->e.GetCharCount(b,index,count);case "ST"->e.GetString(b,index,count);case "DS"->e.GetString(b);case "SB"->e.GetByteCount((String)null);case "SE"->e.GetBytes((String)null);case "MB"->e.GetMaxByteCount(count);case "MC"->e.GetMaxCharCount(count);default->throw new AssertionError(op);};check(p[9].isEmpty()&&(p[7].equals("n")?actual instanceof Integer value&&value==Integer.parseInt(p[8]):Arrays.equals(units(actual),ints(p[8]))),"result "+line);groups++;}catch(Exception ex){failure(ex,p,line);groups++;}
